export class MutationQueue {
  private queue: any[] = [];
  enqueue(mutation: any) { this.queue.push(mutation); }
  flush(ws: WebSocket) {
    while (this.queue.length && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(this.queue.shift()));
    }
  }
}

